def probabilite(favorables, possibles):
    if possibles == 0 or favorables > possibles:
        raise ValueError("cas impossibles")
    return round(favorables / possibles, 3)

def frequence(tirages, valeur):
    if not tirages:
        return 0
    return round(tirages.count(valeur) / len(tirages), 3)

